from h import *
R(9890162,"تاكو القرنبيط والحمص",
"تاكو القرنبيط والحمص هذا نابض بالحياة ومريح وطازج وغني بالنكهة!",
"4 حصص","حصة واحدة",
["4 أكواب زهيرات قرنبيط (حوالي رأس قرنبيط صغير واحد)","1.5 كوب حمص (حوالي علبة 15 أونصة مصفاة ومغسولة)","4 ملاعق كبيرة صلصة صويا","1 ملعقة كبيرة ماء مفلتر","1 ملعقة كبيرة مسحوق الفلفل الحار (تشيلي)","1 ملعقة صغيرة بابريكا مدخنة","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة كمون","ملح وفلفل (حسب الرغبة)","8 قشور تاكو","2 حبة أفوكادو ناضجة","¼ كوب كاجو نيء","2 ملعقة كبيرة عصير ليمون أخضر (حوالي حبة ليمون أخضر كبيرة)","2 ملعقة كبيرة خل التفاح","½ ملعقة صغيرة ملح البحر","⅓ كوب ماء مفلتر (إضافة إلى 1-2 ملعقة كبيرة للحصول على قوام أخف)"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) وبطّن صينية خبز بورق الزبدة.",
"اخلط صلصة الصويا والماء وجميع التوابل في وعاء خلط متوسط. ثم أضف زهيرات القرنبيط والحمص. امزج جيدًا لتتغلف القطع بالتساوي.",
"اشوِ لمدة 20-25 دقيقة تقريبًا حتى تصبح الحواف ذهبية ومقرمشة قليلًا.",
"أثناء الشوي، حضّر كريما الأفوكادو والليمون الأخضر. ضع جميع المكونات في الخلاط وشغّله حتى يصبح ناعمًا، مع البدء بـ ⅓ كوب من الماء. أضف المزيد من الماء إذا رغبت في قوام أخف.",
"اجمع التاكو باستخدام القشور أو التورتيلا المفضلة لديك وضع فوقها كمية وفيرة من كريما الأفوكادو."],
[],
{})
R(9890977,"كوكيز الشورت بريد الخالية من الألبان",
"كوكيز الشورت بريد الخالية من الألبان حلوى ممتعة يستمتع بها الجميع. فهي حلوة بإتقان وهشة و«زبدية» ولذيذة!",
"26 قطعة كوكيز","قطعة كوكيز واحدة",
["1 كوب سمن نباتي (مارجرين) أو زبدة طرية","½ كوب سكر ناعم (سكر بودرة)","1 ملعقة صغيرة مستخلص الفانيليا الطبيعي (اختياري)","1¾ كوب دقيق متعدد الاستخدامات غير مبيّض","1 كوب سكر ناعم (سكر بودرة)","2-3 ملاعق كبيرة ماء","1 قطرة ملون طعام أزرق (احرص على استخدام ماركة نباتية إن فضّلت، أو تجاوزه وأبقِ الغلازورة بيضاء)","رشات حلوى ملونة من اختيارك (احرص على استخدام ماركة نباتية إن فضّلت)"],
["في وعاء كبير، اخفق السمن النباتي بخلاط يدوي لمدة 1-2 دقيقة حتى يصبح هشًا. ثم أضف السكر والفانيليا واستمر في الخلط حتى تمتزج.",
"أضف الدقيق على دفعتين وامزج حتى يمتزج. ستحصل على خليط لا يبدو متماسكًا، لكنه سيتماسك. استخدم يديك لتشكيل العجين على هيئة كرة مسطحة في قاع الوعاء. غطِّه بغلاف التغليف البلاستيكي وضعه في الثلاجة لمدة 2-3 ساعات أو في المجمّد لمدة 15-20 دقيقة.",
"في الأثناء، بطّن صينية خبز كبيرة بورق الزبدة وسخّن الفرن مسبقًا على 350 درجة فهرنهايت (175° مئوية).",
"ضع ورقة من ورق الزبدة على سطح المطبخ وضع العجين البارد فوقها. سوِّ العجين ومدّه باستخدام شوبك مدهون بالدهن حتى يصبح بسماكة ¼ بوصة تقريبًا. ثم استخدم قوالب الكوكيز لتشكيل الكوكيز. انقل الكوكيز بحذر إلى صينية الخبز. ثم أعد فرد العجين المتبقي وسوِّه مجددًا واستمر في تشكيل الكوكيز. كرر ذلك حتى ينفد العجين كله.",
"اخبزها لمدة 15-18 دقيقة، أو حتى تصبح الحواف ذهبية قليلًا. أخرجها من الفرن وانقلها إلى رف تبريد. اتركها تبرد تمامًا قبل وضع الغلازورة.",
"اخلط السكر الناعم مع 2 ملعقة كبيرة من الماء في وعاء صغير وامزج جيدًا. إذا كانت الغلازورة سميكة جدًا، فأضف ملعقة كبيرة أخرى وامزج مجددًا. ثم أضف قطرة من ملون الطعام، إن استخدمته، وامزج حتى يمتزج.",
"استخدم فرشاة سيليكون لدهن الكوكيز بالغلازورة ثم انثر عليها الحلوى الملونة. احرص على إضافة الرشات فور وضع الغلازورة بينما لا تزال رطبة كي تلتصق. اتركها جانبًا لتجف."],
["استخدم قوالب كوكيز قليلة التفاصيل لسهولة العمل. فالقوالب ذات الأخاديد والنقوش المعقدة يصعب تماسك الكوكيز فيها عند نقلها إلى صينية الخبز. والأشكال البسيطة مثل الدوائر أو القلوب أو النجوم أقل عرضة للكسر. ادهن الشوبك بالدهن كي لا يلتصق بالعجين. فهذا سيجعل الكوكيز أنعم، لكن لا تسعَ إلى الكمال. فالغلازورة والرشات ستغطي أسطح الكوكيز على أي حال. وإذا كان الشوبك لا يزال يلتصق بالعجين، فضع ورقة من ورق الزبدة فوقه وافرد العجين فوق الورق. توخَّ الحذر عند نقل كوكيز الشورت بريد إلى صينية الخبز. فالعجين طري، وقد تتكسر الكوكيز إذا استخدمت قوة مفرطة. أحب استخدام شوكة كبيرة أو سكين فطائر لكشط ما تحت الكوكيز أولًا (لـ«فك التصاقها» بالورق)، ثم أرفعها وأنقلها ببطء. لكن إذا تكسرت بعض الكوكيز، فلا تقلق! يمكنك ضغط القطعة برفق لإعادتها معًا بأصابع مدهونة. وإذا تعذر إنقاذها، فأضفها ببساطة إلى كومة العجين المتبقي لإعادة فردها في الجولة التالية. تحدد سماكة العجين وقت الخبز. فإذا فردت العجين أرق، فستُخبز الكوكيز أسرع، أما إذا فردته أسمك، فستحتاج إلى وقت أطول قليلًا في الفرن. ابدأ بتفقدها عند حوالي الدقيقة العاشرة لضمان عدم احتراقها. اترك كوكيز الشورت بريد تبرد تمامًا قبل وضع الغلازورة. فإذا كانت الكوكيز ساخنة جدًا، فستسيل الغلازورة وتتساقط وستذوب الحلوى. وبعد وضع الغلازورة، انثر الحلوى فورًا، قبل أن تتماسك الغلازورة، وإلا فلن تلتصق. المعلومات الغذائية لا تشمل الغلازورة الاختيارية. تُحفظ الكوكيز في الثلاجة لمدة تصل إلى أسبوع أو تُجمَّد في وعاء محكم الإغلاق مناسب للمجمّد لمدة تصل إلى شهرين. افصل بين طبقات الكوكيز بورق الزبدة قبل التجميد."],
{"Glaze (Optional)":"الغلازورة (اختيارية)","Optional Glaze":"الغلازورة الاختيارية"})
R(9892214,"ذرة بالكريمة نباتية [خالية من الزيت]",
"هذه الذرة بالكريمة النباتية غنية بالنكهة بشكل لا يُصدَّق وتتطلب جهدًا قليلًا جدًا.",
"8 حصص","حصة واحدة",
["4 أكواب حبوب ذرة مجمدة (لا حاجة لإذابتها)","400 مل حليب جوز الهند غير المحلى من Thai Kitchen كامل الدسم للحصول على أفضل النتائج* (حوالي 1¾ كوب)","½ كوب حليب الصويا غير المحلى أو حليب نباتي غير محلى من اختيارك","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","2 ملعقة كبيرة شراب القيقب (اختياري، لكن يُنصح به)","½ ملعقة صغيرة رقائق الفلفل الأحمر (اختياري، لكن يُنصح بها)"],
["ضع جميع المكونات في قدر أو مقلاة وامزج جيدًا. اتركها حتى تصل إلى غليان هادئ على نار متوسطة، مع التحريك من حين لآخر. واصل الغليان الهادئ لمدة 8-10 دقائق حتى يتقلص الحجم إلى النصف تقريبًا.",
"ثم انقل 1 كوب من خليط الذرة إلى الخلاط وشغّله حتى يصبح ناعمًا. أعد الذرة المهروسة إلى القدر وحرّك حتى تمتزج. قدّمها دافئة."],
["لتقليل السعرات الحرارية والدهون، استخدم حليب جوز الهند المعلب الخفيف بدلًا من كامل الدسم، لكن لاحظ أن ذلك سيجعل الطبق أقل غنى.","للتحلية، أفضّل شراب القيقب، لكن يمكنك استخدام محليات سائلة أخرى إن فضّلت.","للحصول على وصفة خالية من جوز الهند، استخدم حليبًا نباتيًا آخر، مثل حليب الكاجو أو الصويا. ومرة أخرى، لاحظ أن ذلك سيجعل الطبق أقل غنى.","للحصول على وصفة خالية من الصويا، استخدم أي حليب آخر غير محلى وخالٍ من الألبان من اختيارك.","يُحفظ المتبقي في الثلاجة لمدة تصل إلى 3 أيام. أعد تسخينه على الموقد مع رشة من الحليب أو الماء لتخفيف قوامه."],
{})
R(9897433,"سلطة الدجاج النباتي بالجاك فروت المشوي",
"سلطة الدجاج النباتي الشهية هذه مليئة بنكهة قوية وجريئة، مع قرمشة قليلة وحلاوة وكثير من اللذة. مغطاة بصلصة غنية وكريمية خالية من الزيت.",
"6 حصص","حصة واحدة",
["علبة جاك فروت أخضر صغير (غير ناضج) وزنها 20 أونصة في محلول ملحي أو ماء، وليس في شراب، مصفاة ومغسولة","علبة حمص 15 أونصة مصفاة ومغسولة (أو 1.5 كوب)","½ كوب قطع جوز أو بيكان","½ كوب كرفس مقطع إلى مكعبات (حوالي ساق واحدة)","½ كوب عنب أحمر مقطوع إلى نصفين","¼ كوب بصل أخضر مقطع إلى شرائح رفيعة (حوالي بصلة خضراء واحدة)","¾ كوب كاجو نيء","¾ كوب + 2 ملعقة كبيرة ماء","2 ملعقة كبيرة عصير ليمون (حوالي نصف ليمونة كبيرة)","1 ملعقة صغيرة شبت مجفف","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل أسود"],
["سخّن الفرن مسبقًا على 400° فهرنهايت (205° مئوية) وبطّن صينية خبز كبيرة بورق الزبدة.",
"اغسل الجاك فروت جيدًا جدًا لإزالة المحلول الملحي وفتّت جميع القطع. ضع الجاك فروت المفتت على الصينية مع الحمص وقطع الجوز. اخبزها لمدة 15 دقيقة ثم أخرجها من الفرن.",
"في الأثناء، ضع جميع مكونات الصلصة، مع البدء بـ ¾ كوب من الماء، في خلاط عالي السرعة وشغّله حتى يصبح الخليط ناعمًا وكريميًا. أضف ملعقتي الماء المتبقيتين عند الحاجة لتخفيف الصلصة وأعد الخلط.",
"ضع الجاك فروت والحمص والجوز والكرفس والعنب والبصل الأخضر في وعاء تقديم واسكب الصلصة فوقها. امزج جيدًا وضعها في الثلاجة لمدة ساعة قبل التقديم."],
["استخدم الجاك فروت الأخضر الصغير المعلب في المحلول الملحي أو الماء فقط. لا تستخدم الجاك فروت الطازج، ولا تستخدم الجاك فروت المعلب في شراب.","إذا لم يكن لديك خلاط عالي السرعة، فانقع الكاجو في ماء بارد طوال الليل، أو في ماء مغلي لمدة 15-30 دقيقة، ثم صفِّه. فوقت النقع سيجعل الكاجو ينتفخ ويلين، مما يسهّل خلطه.","طعم هذه السلطة رائع وهي طازجة، لكن طعمها أفضل عند تبريدها لمدة ساعة أو أكثر.","للحصول على وصفة خالية من المكسرات: احذف الجوز أو استبدله ببذور القرع (بيبيتاس) في السلطة. وللصلصة، استخدم بذور عباد الشمس النيئة بدلًا من الكاجو للحصول على نتائج مماثلة.","للحصول على صلصة بنمط المايونيز، استخدم مايونيز نباتيًا جاهزًا أو مايونيز بذور القرع (بيبيتاس) الخالي من الزيت الخاص بي.","يُحفظ المتبقي في الثلاجة في وعاء محكم الإغلاق لمدة 2-3 أيام."],
{"For the Salad":"للسلطة","For the Dressing":"للصلصة"})
R(9898504,"حساء الخضار والشعير",
"حساء الخضار والشعير المنزلي مع الفاصولياء مشبع ولذيذ وسهل التحضير!",
"8 حصص","حصة واحدة",
["1 كوب فاصولياء بيضاء صغيرة (نيفي) أو فاصولياء بيضاء (كلى بيضاء) منقوعة طوال الليل أو بطريقة النقع السريع، انظر الملاحظات أدناه","1 بصلة حمراء","4 جزرات كبيرة","2 كوب بازلاء مجمدة","1 كوب ذرة مجمدة","1 كوب شعير غير مقشر (بوت)","10 أكواب مرق خضار قليل الصوديوم","1.5 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة أوريجانو مجفف","2 حفنة سبانخ صغيرة (بيبي)","ملح وفلفل حسب الرغبة"],
["قشّر البصل وقطّعه إلى أرباع وقشّر الجزر. ضعهما في محضّرة الطعام وشغّلها حتى يصبحا مفرومين ناعمًا. وإذا لم يكن لديك محضّرة طعام، فيمكنك فرمهما ناعمًا يدويًا. ثم انقلهما إلى قدر كبير.",
"أضف جميع المكونات المتبقية باستثناء السبانخ إلى القدر نفسه واتركها حتى تغلي على نار عالية. ثم اخفض الحرارة إلى متوسطة-منخفضة واتركها على نار هادئة مع الغطاء ولكن بشكل مائل قليلًا لمدة 30-40 دقيقة حتى يصبح الشعير والفاصولياء طريين.",
"أطفئ النار وحرّك السبانخ فيه. ستذبل السبانخ بسرعة، ثم قدّم الحساء."],
["لنقع الفاصولياء طوال الليل، غطّها بماء بارد بارتفاع بوصتين فوق الفاصولياء لإتاحة مساحة لتمددها. صفِّها عندما تصبح جاهزة للاستخدام. وإذا لم تنقع الفاصولياء طوال الليل، فاغلِ بعض الماء في قدر أو غلاية وغطِّ الفاصولياء بالماء المغلي لمدة 30 دقيقة. ثم صفِّها واستخدمها كما هو موضح. ولجعل الحساء خاليًا من الغلوتين، يمكنك استخدام الأرز البني بدلًا من الشعير. يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام أو يُجمَّد في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{})
R(9908880,"صلصة معكرونة القرع النباتية",
"صلصة معكرونة القرع النباتية اللذيذة مثالية لوجبة سريعة وسهلة جدًا في أيام الأسبوع، وتستخدم مكونات بسيطة لتقديم الكثير من اللذة.",
"6 حصص","حصة واحدة",
["1.5 كوب مرق خضار قليل الصوديوم","2 كوب هريس القرع","½ ملعقة صغيرة مريمية مجففة","½ ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","½ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل كايين","¼ ملعقة صغيرة زنجبيل مطحون","2 ملعقة كبيرة مسحوق الأروروت أو دقيق متعدد الاستخدامات","½ كوب حليب الصويا أو حليب من اختيارك","450 غرام معكرونة من اختيارك (أحب الفيتوتشيني)"],
["اخلط مرق الخضار وهريس القرع وجميع التوابل ومسحوق الأروروت في قدر متوسط. اتركها على نار متوسطة-منخفضة لمدة 5-6 دقائق مع التحريك المتكرر. ثم أطفئ النار وحرّك فيها الحليب. اتركها جانبًا وأبقها مغطاة.",
"في الأثناء، اترك قدرًا كبيرًا من الماء المملح بوفرة حتى يغلي، واطبخ المعكرونة وفق تعليمات العبوة. صفِّها وأعدها إلى القدر. ثم اسكب الصلصة على المعكرونة وامزج فورًا حتى لا تلتصق المعكرونة ببعضها. يمكنك الاحتفاظ بجزء من الصلصة لتزيين كل طبق أو خلطها كلها.",
"قدّمها مزيّنة برقائق الفلفل الحار وجبن البارميزان النباتي إن رغبت."],
["أضف الملح إلى الماء. أضف كمية كافية من الملح إلى الماء المغلي للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة. الصلصة رائعة مع معكرونة القمح أو معكرونة الكوسا (زودلز) أو الأرز البني أو معكرونة الحمص أو العدس. اطبخ معكرونة القمح «ألدنتي» للحصول على أفضل قوام. («ألدنتي» تعني أن المعكرونة تبقى متماسكة بعد الطبخ، مما يعطي قوامًا مثاليًا في كل لقمة.) وللحصول على وصفة خالية من الغلوتين، استخدم معكرونتك المفضلة الخالية من الغلوتين واطبخها وفق تعليمات العبوة للحصول على معكرونة «ألدنتي». احفظ المعكرونة والصلصة المتبقيتين بشكل منفصل وإلا امتصت المعكرونة كل الصلصة الزائدة. وإذا كنت تطبخ لأطفال انتقائيين في الطعام، فتجاوز فلفل الكايين. وإذا كنت لا تستطيع تناول الصويا (لكن يمكنك تناول المكسرات)، فاستخدم حليب الكاجو أو اللوز غير المحلى. أو جرّب حليب جوز الهند المعلب للحصول على صلصة أغنى. واستخدم النوع الخفيف لتقليل الدهون."],
{})
R(9909062,"لفائف الفلافل المخبوزة السهلة - خالية من الغلوتين",
"لفائف الفلافل المخبوزة الخفيفة لذيذة تمامًا كنسختها التقليدية المقلية، مع سعرات حرارية ودهون أقل.",
"4 حصص (تُنتج حوالي 20-22 قطعة فلافل)","حصة واحدة",
["1 كوب حمص جاف/غير مطبوخ منقوع طوال الليل. (لا تستخدم المعلب)","1 كوب كزبرة خضراء أو بقدونس مفروم تقطيعًا خشنًا وغير مكبوس","1 بصلة صفراء مقطعة تقطيعًا خشنًا","4 ملاعق كبيرة عصير ليمون (حوالي ليمونة كبيرة)","2 ملعقة كبيرة زيت زيتون","1 ملعقة صغيرة ريحان مجفف","2 ملعقة صغيرة مسحوق الثوم","1.5 ملعقة صغيرة كمون","½ ملعقة صغيرة بيكنغ باودر","¾ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل أسود","خبز بيتا من القمح الكامل (خالٍ من الغلوتين عند الحاجة)","طماطم","خيار","بصل أحمر","كزبرة خضراء أو بقدونس أو شبت طازج","طحينة"],
["بطّن صينية خبز بورق الزبدة وسخّن الفرن مسبقًا على 400 درجة فهرنهايت (205° مئوية).",
"صفِّ الحمص جيدًا وضعه في محضّرة الطعام مع جميع المكونات المتبقية. شغّلها حتى يصبح الخليط مفتتًا لكن غير مهروس. لا تفرط في المعالجة.",
"شكّل الخليط على هيئة كرات صغيرة (1-1.5 بوصة)، مع عصر الرطوبة الزائدة بيديك، ثم سوِّها قليلًا وشكّلها على هيئة أقراص/قطع صغيرة. ضعها على صينية الخبز المجهزة.",
"اخبزها لمدة 15 دقيقة ثم اقلب الفلافل واخبزها 5 دقائق أخرى حتى تصبح بنية ذهبية فاتحة. لا تفرط في خبز الفلافل وإلا أصبحت جافة جدًا.",
"قدّمها في خبز البيتا مع الإضافات والصلصات المفضلة لديك أو استخدمها كإضافة فوق السلطات."],
["احرص على تصفية الحمص جيدًا وتجفيفه هو والبقدونس أو الكزبرة الخضراء بالتربيت بمنشفة مطبخ نظيفة قبل نقله إلى محضّرة الطعام. اعصر الرطوبة الزائدة فوق حوض المطبخ عند تشكيل كرات الفلافل، قبل تسويتها على شكل قرص. لا تفرط في معالجة المكونات في محضّرة الطعام. فأنت تريد خليطًا خشنًا قليلًا للحصول على أفضل قوام ممكن. (انظر الصورة أعلاه.) لا تستبدله بالحمص المعلب، فسيكون طريًا جدًا ويغيّر قوام الفلافل. حجم الحصة يمثل ربع الوصفة أو حوالي 5 قطع فلافل من أصل 20 قطعة ناتجة. ولا يشمل الحساب خبز البيتا أو اللفائف أو الإضافات الأخرى. يُحفظ المتبقي في الثلاجة لمدة تصل إلى 4 أيام. احفظه في وعاء محكم الإغلاق وأعد تسخينه في الفرن على 350 درجة فهرنهايت (175° مئوية) لمدة 10 دقائق تقريبًا."],
{"Optional Ingredients":"مكونات اختيارية"})
R(9910859,"حساء البروكلي والبطاطس الصحي",
"حساء البروكلي والبطاطس كريمي قليلًا، وفيه قطع قليلة، ولذيذ جدًا. وصفة الحساء الشهية هذه تبعث على الدفء والتغذية وهي صحية بنسبة 100%.",
"8 حصص","حصة واحدة",
["1 بصلة حمراء كبيرة مفرومة ناعمًا","4 جزرات كبيرة مقطعة إلى شرائح رفيعة","2 رطل بطاطس يوكون جولد مقشرة ومقطعة إلى مكعبات","علبة فاصولياء بيضاء (كلى بيضاء) وزنها 19 أونصة مصفاة ومغسولة","1 رأس بروكلي كبير مقطع إلى زهيرات بحجم لقمة، حوالي 8 أكواب من الزهيرات الصغيرة","6 أكواب مرق خضار قليل الصوديوم","½ كوب خميرة غذائية","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة زعتر مجفف","ملح البحر حسب الرغبة","1 كوب حليب الكاجو غير المحلى أو حليب الصويا أو حليب جوز الهند"],
["ضع البصل والجزر في قدر كبير مع ملعقة كبيرة أو ملعقتين من الماء. قلّبها حتى تلين قليلًا، حوالي دقيقتين.",
"أضف البطاطس والفاصولياء والمرق والخميرة الغذائية والزعتر ومسحوق الثوم إلى القدر واتركها حتى تغلي على نار عالية. اخفض الحرارة واتركها على نار هادئة حتى تصبح البطاطس سهلة الاختراق بالشوكة، حوالي 8 دقائق. ثم أضف البروكلي واتركها على نار هادئة 5 دقائق أخرى.",
"أطفئ النار وباستخدام ملعقة مثقبة، أخرج حوالي 4 أكواب من الخضار واتركها جانبًا. ثم اهرس باقي الحساء في القدر باستخدام خلاط يدوي. أو يمكنك نقله إلى خلاط عادي على دفعات، مع توخي الحذر عند هرس السوائل الساخنة. أعد الأكواب الأربعة المحتفظ بها من الخضار إلى القدر، وحرّك فيه الحليب النباتي وتذوّق للتأكد من الملح. أضفت ½ ملعقة صغيرة عند هذه المرحلة، لكن تبّله حسب ذوقك. ثم قدّمه واستمتع به.",
"اضبط إنستانت بوت على وظيفة التقليب (السوتيه)، ثم أضف البصل والجزر مع ملعقة كبيرة أو ملعقتين من الماء. قلّبها حتى تلين قليلًا، حوالي دقيقتين.",
"أضف جميع المكونات المتبقية ما عدا الحليب وأغلق الغطاء، مع التأكد من أن الصمام في وضع الإغلاق. اطبخها على الضغط العالي لمدة 7 دقائق ثم حرّر البخار بسرعة من الصمام. انزع الغطاء عندما يكون ذلك آمنًا.",
"استخدم ملعقة مثقبة لإخراج 4 أكواب من الخضار واتركها جانبًا. ثم اهرس باقي الحساء باستخدام خلاط يدوي. أو يمكنك نقله إلى خلاط عادي على دفعات، مع توخي الحذر عند هرس السوائل الساخنة.",
"أعد الخضار المحتفظ بها إلى القدر، وحرّك فيه الحليب وتذوّق للتأكد من الملح. أضفت ½ ملعقة صغيرة عند هذه المرحلة، لكن تبّله حسب ذوقك. ثم قدّمه واستمتع به."],
["أحب هذا الحساء بقطع كثيرة نسبيًا، لكن إذا كنت تقدمه لأطفال انتقائيين في الطعام، فيمكنك هرس الحساء بالكامل بدلًا من الاحتفاظ ببعض الخضار الأكثر خشونة. يمكنك استخدام الخضار المحتفظ بها لإعادتها إلى القدر، أو استخدامها لتزيين كل وعاء من الحساء. وإذا كنت تتجنب المكسرات، فاستخدم حليب الصويا أو جوز الهند بدلًا من حليب الكاجو. كما يمكنك استخدام حليب جوز الهند المعلب إذا أردت قوامًا أغنى وأكثر كريمية، لكن ذلك سيضيف مزيدًا من الدهون. لقد أبقيت التتبيل بسيطًا هنا لإرضاء بعض الأطفال الانتقائيين في الطعام، لكن إذا أردت تعزيز النكهة، فيمكنك إضافة بعض الكمون أو البابريكا أو حتى قليل من الكايين لإضافة حرارة خفيفة."],
{"Instant Pot Directions":"طريقة إنستانت بوت"})
